import{_ as a,o,c as e,ag as r}from"./chunks/framework.CAXxHpAX.js";const c=JSON.parse('{"title":"道教学人入口","description":"","frontmatter":{},"headers":[],"relativePath":"30-学习路径/path-道教学人.md","filePath":"30-学习路径/path-道教学人.md","lastUpdated":1778155802000}'),l={name:"30-学习路径/path-道教学人.md"};function i(d,t,h,u,q,n){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="道教学人入口" tabindex="-1">道教学人入口 <a class="header-anchor" href="#道教学人入口" aria-label="Permalink to &quot;道教学人入口&quot;">​</a></h1><blockquote><p>如果你练过丹道、气功、站桩，或读过道德经，从这里开始了空居士的体系。</p></blockquote><hr><h2 id="你可能已经在修" tabindex="-1">你可能已经在修 <a class="header-anchor" href="#你可能已经在修" aria-label="Permalink to &quot;你可能已经在修&quot;">​</a></h2><ul><li><strong>丹道/周天</strong> → 了空居士走的是<strong>顿超法门</strong>（天元丹法），不搞采气练气，一个动作完成所有</li><li><strong>气功/站桩</strong> → 他的方法更简单——&quot;轻轻意守手指脚趾&quot;，不守丹田，自然呼吸</li><li><strong>道德经</strong> → 他对&quot;无为&quot;&quot;守中&quot;&quot;道法自然&quot;有非常务实的解读</li></ul><hr><h2 id="推荐学习路径" tabindex="-1">推荐学习路径 <a class="header-anchor" href="#推荐学习路径" aria-label="Permalink to &quot;推荐学习路径&quot;">​</a></h2><h3 id="第一步-先了解-顿超法门" tabindex="-1">第一步：先了解&quot;顿超法门&quot; <a class="header-anchor" href="#第一步-先了解-顿超法门" aria-label="Permalink to &quot;第一步：先了解&quot;顿超法门&quot;&quot;">​</a></h3><p>如果你之前学的是渐修丹法（筑基→小周天→大周天→…），先理解他为什么走另一条路：</p><ol><li><strong>不采气、不练气、不行气</strong> —— &quot;你们跟我学的，就不用搞那些采气了&quot;</li><li><strong>直接从中丹田入手</strong> —— &quot;神守黄房&quot;（轻轻返观整个体腔）</li><li><strong>师力加持</strong> —— &quot;我师父当年是以师力加持的，刹那间就通大周天了&quot;</li></ol><p>读：<a href="/10-核心模型/model-性命双修">性命双修模型</a>（重点关注&quot;顿法·渐法之辨&quot;节） 原文入口：<a href="/60-原文段落/中论丹道-师力加持">中论丹道-师力加持</a>、<a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a></p><h3 id="第二步-理解-宇宙统一场" tabindex="-1">第二步：理解&quot;宇宙统一场&quot; <a class="header-anchor" href="#第二步-理解-宇宙统一场" aria-label="Permalink to &quot;第二步：理解&quot;宇宙统一场&quot;&quot;">​</a></h3><p>他用现代物理学的&quot;场&quot;重新定义了&quot;道&quot;：</p><ul><li>道 = 宇宙统一场 = 万物最底层的统一能量场</li><li>修行 = &quot;不是练出来的，是融进去的&quot;</li><li>聚气 = &quot;有为法，是我执，跟大自然能量场不沟通&quot;</li></ul><p>读：<a href="/10-核心模型/model-天人合一">天人合一模型</a> 原文入口：<a href="/60-原文段落/论坛语录-宇宙统一场">论坛语录-宇宙统一场</a>、<a href="/60-原文段落/虚无中的共振-能量共振">虚无中的共振-能量共振</a></p><h3 id="第三步-实修方法" tabindex="-1">第三步：实修方法 <a class="header-anchor" href="#第三步-实修方法" aria-label="Permalink to &quot;第三步：实修方法&quot;">​</a></h3><ul><li>静坐方法：<a href="/60-原文段落/五篇灵文-温养章全段">五篇灵文-温养章全段</a> — 神守黄房，似守非守</li><li>念佛替代意守：<a href="/60-原文段落/念佛-显现极乐">念佛-显现极乐</a> — 心念耳闻+显现极乐</li><li>日常收功：<a href="/60-原文段落/修行即生活-收功">修行即生活-收功</a></li><li>意守手脚：<a href="/60-原文段落/修行即生活-意守手指脚趾">修行即生活-意守手指脚趾</a></li></ul><h3 id="第四步-了解心法" tabindex="-1">第四步：了解心法 <a class="header-anchor" href="#第四步-了解心法" aria-label="Permalink to &quot;第四步：了解心法&quot;">​</a></h3><p>丹道重&quot;命功&quot;（身体修炼），了空居士强调&quot;性命双修&quot;——心和身要一起转化：</p><ul><li><a href="/10-核心模型/model-对境不住">对境不住</a> — 静坐中杂念来了怎么办</li><li><a href="/10-核心模型/model-自然务实">自然务实</a> — 修行化繁为简</li></ul><hr><h2 id="你可能发现的不同" tabindex="-1">你可能发现的不同 <a class="header-anchor" href="#你可能发现的不同" aria-label="Permalink to &quot;你可能发现的不同&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统丹道/气功常见说法</th><th>了空居士的说法</th></tr></thead><tbody><tr><td>意守下丹田</td><td>轻轻返观中丹田（膻中一带覆盖整个体腔）</td></tr><tr><td>调息（顺/逆腹式呼吸）</td><td>自然呼吸就好</td></tr><tr><td>采气、练气、行气</td><td>不采自足，&quot;但安神息，不运火而火自运&quot;</td></tr><tr><td>文火/武火有讲究</td><td>&quot;似守非守&quot;就是全部火候</td></tr><tr><td>先修命后修性</td><td>性功命功同时完成——轻轻返观一个动作，心和身一起转</td></tr><tr><td>百日筑基后才能通周天</td><td>师力加持下可能&quot;刹那间通大周天&quot;</td></tr></tbody></table><hr><h2 id="丹道概念词典" tabindex="-1">丹道概念词典 <a class="header-anchor" href="#丹道概念词典" aria-label="Permalink to &quot;丹道概念词典&quot;">​</a></h2><p><a href="/50-概念资料/50-概念资料_INDEX">概念词典</a></p><ul><li><a href="/50-概念资料/dict-丹田">dict-丹田</a> / <a href="/50-概念资料/dict-小周天">dict-小周天</a> / <a href="/50-概念资料/dict-大周天">dict-大周天</a></li><li><a href="/50-概念资料/dict-炼精化气">dict-炼精化气</a> / <a href="/50-概念资料/dict-炼气化神">dict-炼气化神</a> / <a href="/50-概念资料/dict-炼神还虚">dict-炼神还虚</a></li><li><a href="/50-概念资料/dict-形神俱妙">dict-形神俱妙</a></li></ul><h2 id="丹道与道家金句" tabindex="-1">丹道与道家金句 <a class="header-anchor" href="#丹道与道家金句" aria-label="Permalink to &quot;丹道与道家金句&quot;">​</a></h2><ul><li><a href="/40-原话金句/quote-丹道">丹道金句</a> — 顿超法门、静坐要诀</li><li><a href="/40-原话金句/quote-道家">道家金句</a> — 道德经原话</li></ul><hr><blockquote><p>创建日期：2026-05-07</p></blockquote>',31)])])}const f=a(l,[["render",i]]);export{c as __pageData,f as default};
